const IpLogEntry* matchingIp(const TpLogEntry& tp){if(!tp.decoded)return nullptr;const IpLogEntry* best=nullptr;uint32_t bestDelta=501;for(size_t n=0;n<ipLogCount;++n){const IpLogEntry& ip=ipLog[(ipLogHead+kLogEntries-1-n)%kLogEntries];const uint32_t delta=tp.ms>ip.ms?tp.ms-ip.ms:ip.ms-tp.ms;if(delta<bestDelta&&tp.source==ip.source&&tp.destination==ip.destination&&tp.group==ip.group&&tp.apci==ip.apci&&tp.apduLen==ip.apduLen&&!memcmp(tp.apdu,ip.apdu,tp.apduLen)){best=&ip;bestDelta=delta;}}return best;}
