template<typename Writer> void writeTunnelSection(Writer& r){char v[192];r.write("<section class='card'><h2>Tunneling unicast ETS6</h2><div class='metrics'>");metric(r,"Etat serveur",tunnel.enabled?"ACTIVE MANUELLEMENT":"DESACTIVE PAR DEFAUT");metric(r,"NCN5130",tunnel.ready?"Mode normal pret":"Bus monitor passif / transition");for(uint8_t i=0;i<2;++i){TunnelState& slot=tunnels[i];snprintf(v,sizeof(v),"%s, canal %u, adresse %u.%u.%u",slot.connected?"Connectee":"Libre",unsigned(slot.channel),(slot.address>>12)&15,(slot.address>>8)&15,slot.address&255);metric(r,i?"Tunnel 2":"Tunnel 1",v);IPAddress peer(slot.remote);snprintf(v,sizeof(v),"%s control=%u data=%u",peer.toString().c_str(),slot.controlPort,slot.dataPort);metric(r,i?"Endpoint tunnel 2":"Endpoint tunnel 1",slot.connected?v:"Aucun");snprintf(v,sizeof(v),"req=%lu ack=%lu TP=%lu/%lu/%lu ind=%lu",slot.requests,slot.acks,slot.tpQueued,slot.tpConfirmed,slot.tpFailed,slot.indications);metric(r,i?"Compteurs tunnel 2":"Compteurs tunnel 1",v);}metric(r,"Session gestion",management.connected?"Connectee":"Aucune");snprintf(v,sizeof(v),"%u",unsigned(management.channel));metric(r,"Canal gestion",v);metric(r,"Interface KNX","1.1.253");metric(r,"Adresses clients tunnel","1.1.254 et 1.1.252");metric(r,"Tunnels disponibles","Deux; gestion separee");metric(r,"Point de terminaison","192.0.2.156:3671 UDP");IPAddress mgmtPeer(management.remote);snprintf(v,sizeof(v),"%s control=%u data=%u",mgmtPeer.toString().c_str(),management.controlPort,management.dataPort);metric(r,"Endpoint gestion",management.connected?v:"Aucun");snprintf(v,sizeof(v),"%lu/%lu/%lu/%lu",management.connects,management.rejected,management.disconnects,management.expirations);metric(r,"Gestion connect/refus/disconnect/expire",v);snprintf(v,sizeof(v),"%lu/%lu/%lu",management.requests,management.acks,management.unsupported);metric(r,"Gestion requetes/ACK/non implemente",v);metric(r,"Dernier etat gestion",management.last);IPAddress lastPeer(tunnel.lastConnectRemote);snprintf(v,sizeof(v),"%s:%u",lastPeer.toString().c_str(),tunnel.lastConnectPort);metric(r,"Dernier emetteur CONNECT",tunnel.lastConnectRequestLen?v:"Aucun");snprintf(v,sizeof(v),"0x%02X",tunnel.lastConnectStatus);metric(r,"Dernier statut CONNECT",v);snprintf(v,sizeof(v),"%lu / %lu",tunnels[0].connects+tunnels[1].connects,tunnel.rejected);metric(r,"Tunnels connectes / refuses",v);snprintf(v,sizeof(v),"%lu / %lu",tunnels[0].disconnects+tunnels[1].disconnects,tunnels[0].expirations+tunnels[1].expirations);metric(r,"Tunnel DISCONNECT / expirations",v);snprintf(v,sizeof(v),"%lu / %lu",tunnels[0].indications+tunnels[1].indications,tunnel.udpTxDrops+tunnels[1].udpTxDrops);metric(r,"Indications IP / pertes TX",v);r.write("</div><h3>Dernier handshake brut</h3><p>CONNECT_REQUEST <code>");writeHex(r,tunnel.lastConnectRequest,tunnel.lastConnectRequestLen);r.write("</code></p><p>CONNECT_RESPONSE <code>");writeHex(r,tunnel.lastConnectResponse,tunnel.lastConnectResponseLen);r.write("</code></p><form method='post' action='/knx-diagnostic'><input type='hidden' name='action' value='tunnel_enable'><button type='submit'>Activer le tunnel ETS6</button></form><form method='post' action='/knx-diagnostic'><input type='hidden' name='action' value='tunnel_disable'><button type='submit'>Desactiver et revenir en Busmon</button></form><p class='muted'>Deux tunnels ETS6 au maximum, adresses distinctes 1.1.254 et 1.1.252. Le routage multicast reste desactive. Une activation ne lance aucune commande TP. Aucun telechargement.</p></section>");}
